//! Byte-for-byte parity with the Python reference codecs, over the captured corpus.
//!
//! The fixture is generated by `scripts/gen-protocol-fixture.py` FROM the Python
//! implementation (`services/world/src/azoth_world/javelin/`), so this test is the
//! "compare Rust and Python at the wire boundary using the same fixtures" rule in
//! `docs/ROADMAP.md` section 4 rather than a second hand-written expectation.
//!
//! What it asserts, and why each one matters:
//!
//! * every captured varint case encodes to the exact bytes Python produces, and decodes
//!   back to the same value;
//! * every captured bundle body DECODES, re-ENCODES to the identical bytes, and reports
//!   the same replication counter, payload length and first record header — so the port
//!   cannot silently change what a client would receive;
//! * the record-1 (local-player metadata) fragment boundaries and (key, type) pairs match
//!   the layout derived from the CLIENT's own readers, which cannot be recomputed from
//!   the bytes;
//! * the captured player position pair is still at payload offset 38332 of the spawn
//!   record — the anchor `rep.py::apply_position_override` matches on, so a layout change
//!   that would silently stop the server owning the player's position fails here.

use std::path::PathBuf;

use azoth_protocol::bundle::{decode_bundle, encode_bundle, Fragment};
use azoth_protocol::varint;

/// The bytes of the captured local-player position, big-endian float32 x and y.
/// `rep.py::CAPTURED_PLAYER_POSITION`; the client's own accessor reported these values.
const CAPTURED_POSITION: [u8; 8] = [0x46, 0x11, 0xfe, 0x91, 0x45, 0x2e, 0x2b, 0xb9];
const SPAWN_POSITION_OFFSET: usize = 38332;

fn hex_decode(text: &str) -> Vec<u8> {
    assert!(text.len() % 2 == 0, "odd-length hex line");
    (0..text.len() / 2)
        .map(|i| u8::from_str_radix(&text[2 * i..2 * i + 2], 16).expect("hex"))
        .collect()
}

struct VarintCase {
    value: u64,
    hex: String,
    size: usize,
}

struct BundleCase {
    seq: String,
    replication_seq: u64,
    payload_len: usize,
    first_record_id: i32,
    first_record_fragments: i32,
    body: Vec<u8>,
}

struct Fixture {
    varints: Vec<VarintCase>,
    bundles: Vec<BundleCase>,
    boundaries: Vec<usize>,
    fragments: Vec<Fragment>,
}

fn load_fixture() -> Fixture {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("state-bundles.txt");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|err| panic!("read {}: {err}", path.display()));

    let mut varints = Vec::new();
    let mut bundles = Vec::new();
    let mut boundaries = Vec::new();
    let mut fragments = Vec::new();

    let lines: Vec<&str> = text.lines().collect();
    let mut i = 0usize;
    while i < lines.len() {
        let line = lines[i].trim();
        if line.is_empty() || line.starts_with('#') {
            i += 1;
            continue;
        }
        let fields: Vec<&str> = line.split_whitespace().collect();
        match fields[0] {
            "varint" => {
                varints.push(VarintCase {
                    value: fields[1].parse().expect("varint value"),
                    hex: fields[2].to_string(),
                    size: fields[3].parse().expect("varint size"),
                });
                i += 1;
            }
            "bundle" => {
                let body = hex_decode(lines[i + 1].trim());
                bundles.push(BundleCase {
                    seq: fields[1].to_string(),
                    replication_seq: fields[2].parse().expect("replication seq"),
                    payload_len: fields[3].parse().expect("payload len"),
                    first_record_id: fields[4].parse().expect("first record id"),
                    first_record_fragments: fields[5].parse().expect("first record fragments"),
                    body,
                });
                i += 2;
            }
            "boundary" => {
                boundaries.push(fields[1].parse().expect("boundary"));
                i += 1;
            }
            "frag" => {
                let payload = hex_decode(lines[i + 1].trim());
                assert_eq!(payload.len(), fields[3].parse::<usize>().unwrap());
                fragments.push(Fragment {
                    key: fields[1].parse().expect("frag key"),
                    type_index: fields[2].parse().expect("frag type"),
                    payload,
                });
                i += 2;
            }
            other => panic!("unknown fixture directive {other:?}"),
        }
    }

    assert!(!varints.is_empty(), "no varint cases in the fixture");
    assert!(!bundles.is_empty(), "no bundle cases in the fixture");
    assert!(!fragments.is_empty(), "no fragment cases in the fixture");
    Fixture {
        varints,
        bundles,
        boundaries,
        fragments,
    }
}

#[test]
fn every_captured_varint_case_matches_python() {
    let fixture = load_fixture();
    for case in &fixture.varints {
        let encoded = varint::encode(case.value).expect("encode");
        assert_eq!(
            encoded.iter().map(|b| format!("{b:02x}")).collect::<String>(),
            case.hex,
            "value {} encoded differently",
            case.value
        );
        assert_eq!(varint::size_of(case.value).unwrap(), case.size);
        let (decoded, next) = varint::decode(&encoded, 0).expect("decode");
        assert_eq!(decoded, case.value);
        assert_eq!(next, encoded.len());
    }
    assert!(fixture.varints.len() >= 20);
}

#[test]
fn every_captured_bundle_round_trips_byte_for_byte() {
    let fixture = load_fixture();
    for case in &fixture.bundles {
        let parsed = decode_bundle(&case.body, true)
            .unwrap_or_else(|err| panic!("seq {} failed to decode: {err}", case.seq));
        assert_eq!(parsed.replication_seq, case.replication_seq, "seq {}", case.seq);
        assert_eq!(parsed.payload.len(), case.payload_len, "seq {}", case.seq);
        assert_eq!(
            i32::from(parsed.payload[0]),
            case.first_record_id,
            "seq {} first record id",
            case.seq
        );
        assert_eq!(
            i32::from(parsed.payload[1]),
            case.first_record_fragments,
            "seq {} first record fragment count",
            case.seq
        );
        let re_encoded = encode_bundle(parsed.replication_seq, &parsed.payload);
        assert_eq!(
            re_encoded, case.body,
            "seq {} did not re-encode identically",
            case.seq
        );
    }
    assert!(fixture.bundles.len() >= 40, "fixture lost bundles");
}

#[test]
fn the_player_record_layout_matches_the_client_derived_boundaries() {
    let fixture = load_fixture();
    // The record-1 layout is protocol data measured from the client's own readers, so
    // the Rust side must not recompute it: it asserts the recorded values instead.
    assert_eq!(
        fixture.boundaries,
        vec![2, 60, 3955, 4295, 4301, 4498, 5335, 5386, 7125]
    );
    assert_eq!(fixture.fragments.len(), fixture.boundaries.len());

    let keys: Vec<u64> = fixture.fragments.iter().map(|f| f.key).collect();
    assert_eq!(keys, vec![55, 19, 73, 9, 72, 74, 16, 22, 44]);
    let types: Vec<u64> = fixture.fragments.iter().map(|f| f.type_index).collect();
    assert_eq!(types, vec![4176, 3133, 5606, 3935, 5485, 5691, 11, 3857, 4236]);

    // Re-composing the record from its fragments must reproduce the record header the
    // fixture recorded, which is what makes "the server composes the player's state"
    // safe to switch on.
    let record_body = fixture
        .bundles
        .iter()
        .find(|b| b.payload_len == 7154)
        .expect("the record-1 bundle is in the fixture");
    let parsed = decode_bundle(&record_body.body, true).expect("decode");
    let mut rebuilt = vec![1u8, fixture.fragments.len() as u8];
    for fragment in &fixture.fragments {
        rebuilt.extend_from_slice(&fragment.encode());
    }
    assert_eq!(rebuilt, parsed.payload, "fragment recomposition changed the record");
}

#[test]
fn the_spawn_record_still_carries_the_position_at_the_measured_offset() {
    let fixture = load_fixture();
    let spawn = fixture
        .bundles
        .iter()
        .find(|b| b.payload_len == 46393)
        .expect("the spawn record is in the fixture");
    let parsed = decode_bundle(&spawn.body, true).expect("decode");
    assert_eq!(parsed.payload[0], 1, "the spawn record is record id 1");
    assert_eq!(parsed.payload[1], 48, "with 48 fragments");
    let at = parsed
        .payload
        .windows(CAPTURED_POSITION.len())
        .position(|w| w == CAPTURED_POSITION)
        .expect("the captured position pair is in the spawn payload");
    assert_eq!(
        at, SPAWN_POSITION_OFFSET,
        "the position anchor moved; rep.py's override matches on the VALUE, so this \
         failing means the capture or the parser changed"
    );
    // And it is absent from the record-1 bundle the state stream sends, which is why the
    // position has to be handled at spawn.
    let record_one = fixture
        .bundles
        .iter()
        .find(|b| b.payload_len == 7154)
        .expect("record-1 bundle");
    let record_one = decode_bundle(&record_one.body, true).expect("decode");
    assert!(
        !record_one
            .payload
            .windows(CAPTURED_POSITION.len())
            .any(|w| w == CAPTURED_POSITION),
        "the streamed record-1 bundle must not carry the spawn position pair"
    );
}
